PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role in ('Admin','Viewer')),disabled INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS media(id TEXT PRIMARY KEY,media_type TEXT NOT NULL,title TEXT NOT NULL,original_title TEXT,sort_title TEXT,year INTEGER,imdb_id TEXT,tmdb_id TEXT,filename TEXT NOT NULL,size_bytes INTEGER NOT NULL,sha256 TEXT NOT NULL,resolution TEXT,video_codec TEXT,audio_codec TEXT,subtitle_languages TEXT,runtime_minutes INTEGER,plot TEXT,poster_url TEXT,backdrop_url TEXT,mime_type TEXT,popularity INTEGER NOT NULL DEFAULT 0,archived_at TEXT);
CREATE VIRTUAL TABLE IF NOT EXISTS media_fts USING fts5(title,original_title,imdb_id,tmdb_id,plot,content='media',content_rowid='rowid');
CREATE TABLE IF NOT EXISTS genres(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL); CREATE TABLE IF NOT EXISTS actors(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL); CREATE TABLE IF NOT EXISTS studios(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS media_genres(media_id TEXT REFERENCES media(id) ON DELETE CASCADE,genre_id INTEGER REFERENCES genres(id),PRIMARY KEY(media_id,genre_id));
CREATE TABLE IF NOT EXISTS media_actors(media_id TEXT REFERENCES media(id) ON DELETE CASCADE,actor_id INTEGER REFERENCES actors(id),PRIMARY KEY(media_id,actor_id));
CREATE TABLE IF NOT EXISTS media_studios(media_id TEXT REFERENCES media(id) ON DELETE CASCADE,studio_id INTEGER REFERENCES studios(id),PRIMARY KEY(media_id,studio_id));
CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,kind TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chunks(id INTEGER PRIMARY KEY,media_id TEXT REFERENCES media(id),part_number INTEGER NOT NULL,channel_id INTEGER REFERENCES channels(id),message_id INTEGER NOT NULL,size_bytes INTEGER NOT NULL,sha256 TEXT NOT NULL,UNIQUE(media_id,part_number));
CREATE TABLE IF NOT EXISTS manifests(media_id TEXT PRIMARY KEY REFERENCES media(id),channel_id INTEGER REFERENCES channels(id),message_id INTEGER NOT NULL,sha256 TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS upload_jobs(id TEXT PRIMARY KEY,media_id TEXT,status TEXT,queued_at TEXT DEFAULT CURRENT_TIMESTAMP,started_at TEXT,finished_at TEXT,error TEXT);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id TEXT,action TEXT NOT NULL,resource TEXT,metadata TEXT,ip TEXT,user_agent TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS cache_objects(object_key TEXT PRIMARY KEY,media_id TEXT,size_bytes INTEGER NOT NULL,hits INTEGER NOT NULL DEFAULT 0,last_accessed_at TEXT DEFAULT CURRENT_TIMESTAMP,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE VIEW IF NOT EXISTS cache_stats AS SELECT count(*) objects, coalesce(sum(size_bytes),0) bytes, coalesce(sum(hits),0) hits FROM cache_objects;
CREATE INDEX IF NOT EXISTS idx_media_title ON media(title); CREATE INDEX IF NOT EXISTS idx_media_year ON media(year); CREATE INDEX IF NOT EXISTS idx_chunks_media ON chunks(media_id,part_number);

CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,encrypted INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,updated_by TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS secret_store(id TEXT PRIMARY KEY,secret_name TEXT UNIQUE NOT NULL,ciphertext TEXT NOT NULL,key_version INTEGER NOT NULL,rotated_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS channel_mappings(id INTEGER PRIMARY KEY AUTOINCREMENT,media_type TEXT NOT NULL,title_from TEXT NOT NULL,title_to TEXT NOT NULL,channel_name TEXT NOT NULL,channel_id TEXT,enabled INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS upload_rules(id INTEGER PRIMARY KEY CHECK(id=1),monthly_upload_limit_bytes INTEGER NOT NULL,chunk_size_bytes INTEGER NOT NULL,scheduling_enabled INTEGER NOT NULL,quotas_enabled INTEGER NOT NULL,sha_validation_enabled INTEGER NOT NULL,timezone TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS upload_windows(id INTEGER PRIMARY KEY AUTOINCREMENT,rule_id INTEGER NOT NULL REFERENCES upload_rules(id) ON DELETE CASCADE,weekday INTEGER NOT NULL,start_time TEXT NOT NULL,end_time TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cache_rules(id INTEGER PRIMARY KEY CHECK(id=1),r2_cache_size_bytes INTEGER NOT NULL,eviction_policy TEXT NOT NULL,cache_duration_seconds INTEGER NOT NULL,popularity_threshold INTEGER NOT NULL,preload_enabled INTEGER NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cloudflare_config(id INTEGER PRIMARY KEY CHECK(id=1),account_id TEXT,worker_url TEXT,worker_secret_ref TEXT,d1_database_id TEXT,kv_namespace TEXT,r2_bucket TEXT,pages_project TEXT,domain_name TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS telegram_config(id INTEGER PRIMARY KEY CHECK(id=1),phone_number_ref TEXT,api_id_ref TEXT,api_hash_ref TEXT,session_name TEXT,session_ref TEXT,session_status TEXT NOT NULL DEFAULT 'disconnected',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS jellyfin_config(id INTEGER PRIMARY KEY CHECK(id=1),server_url TEXT,api_key_ref TEXT,username TEXT,password_ref TEXT,library_paths TEXT NOT NULL DEFAULT '[]',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tmdb_config(id INTEGER PRIMARY KEY CHECK(id=1),api_key_ref TEXT,language TEXT,region TEXT,poster_sync INTEGER NOT NULL DEFAULT 1,backdrop_sync INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS health_checks(id INTEGER PRIMARY KEY AUTOINCREMENT,component TEXT NOT NULL,status TEXT NOT NULL,last_check TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,latency_ms INTEGER,error TEXT);
CREATE INDEX IF NOT EXISTS idx_health_component ON health_checks(component,last_check);
